    "body": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Synced Reading Page</title>\n    <link rel=\"stylesheet\" href=\"styles.css?v=6\" />\n  </head>\n  <body class=\"reader-body\">\n    <main class=\"reader-shell\">\n      <section class=\"reader-page\">\n        <div id=\"marginalia-layer\" class=\"marginalia-layer\" aria-hidden=\"true\"></div>\n\n        <header class=\"reader-header\">\n          <div>\n            <h1 id=\"page-title\">Loading...</h1>\n          </div>\n        </header>\n\n        <p class=\"reader-hint\">Tap a word to check its meaning.</p>\n\n        <article id=\"transcript\" class=\"transcript\" aria-label=\"Synced transcript\"></article>\n\n        <footer class=\"player-bar\">\n          <div class=\"transport-controls\">\n            <button id=\"play-button\" class=\"play-button\" aria-label=\"Play\" disabled>\n              <span class=\"play-icon\" aria-hidden=\"true\"></span>\n            </button>\n            <button id=\"pause-button\" class=\"pause-button\" aria-label=\"Pause\" disabled>\n              <span class=\"pause-icon\" aria-hidden=\"true\"></span>\n            </button>\n          </div>\n          <div class=\"timeline\">\n            <div id=\"progress\" class=\"progress\"></div>\n          </div>\n          <span id=\"time-label\" class=\"time-label\">0:00</span>\n          <audio id=\"audio\" preload=\"auto\"></audio>\n        </footer>\n\n        <section id=\"word-sheet\" class=\"word-sheet\" aria-live=\"polite\">\n          <div class=\"word-sheet-handle\"></div>\n          <div class=\"word-sheet-top\">\n            <div class=\"word-sheet-heading\">\n              <div class=\"language-pill\">\n                <span aria-hidden=\"true\">Translation</span>\n                <select id=\"language-select\" class=\"language-select\" aria-label=\"Translation language\">\n                  <option>Turkish</option>\n                  <option>Spanish</option>\n                  <option>French</option>\n                  <option>Italian</option>\n                  <option>German</option>\n                  <option>Portuguese</option>\n                  <option>Arabic</option>\n                  <option>Chinese</option>\n                  <option>Japanese</option>\n                  <option>Korean</option>\n                  <option>Polish</option>\n                  <option>Russian</option>\n                </select>\n              </div>\n              <h2 id=\"sheet-word\">Choose a word</h2>\n            </div>\n            <button id=\"sheet-close\" class=\"sheet-close\" aria-label=\"Close word help\">&times;</button>\n          </div>\n\n          <div id=\"sheet-content\" class=\"sheet-content\">\n            <p>Select your language, then tap any word for a definition and translation.</p>\n          </div>\n        </section>\n      </section>\n    </main>\n\n    <script src=\"play.js?v=6\"></script>\n  </body>\n</html>\n"
